      "Verdict: FAIL — The Path of The Fall.\nA seat majority is used to claim a popular mandate, masking the reality that support actually declined. The system's quirks are substituted for the people's will.",
      "The Scottish election resulted in the SNP and Greens taking 73 seats. While they celebrate this as a record-breaking pro-independence majority, the victory relies on electoral system disproportionality rather than a majority of the voters.",
      "The Bright Side:\nThe regional list system is designed to prevent one-party monopoly and encourage coalition building. A joint majority represents a stable, collaborative governing coalition.",
      "The Breakdown & Plane Error:\nThe claim treats the seat count (WHAT) as proof of the popular will (WHO). It is a bait-and-switch: they bait voters with a democratic mandate, but switch it to extract partisan power despite a minority of votes.",
      "The Trajectory: The Path of The Fall.\nWhen we map the gap between the stated ideal of popular self-determination and the actual action of exploiting seat-skew...",
      "...it plots a direct trajectory toward the Greatest Lie. With u at -1.0 and psi at +1.0, the coalition actively projects systemic mandate while extracting localized party benefit from a minority electoral base.",
      "The Unavoidable Truth: A minority of voters cannot be turned into a majority mandate without eroding trust.\n\nThe Unavoidable Lie: That winning a majority of seats under a skewed system proves most citizens support your goal.",
      "Alethekanon:\nDemocracy requires mathematical consistency. When 41% of the popular vote is translated into 57% of the seats and used to claim a 100% mandate, the structural logic of representation fails. The map is not the territory.",
      "Awwthekanon:\nIt hurts to see people's deep hopes for self-determination used as tools for party power. True consensus can't be forced by numbers; it has to be built by listening to the real anxieties of the whole community.",
      "Brothekanon:\nSo you lose votes, fail to get a majority alone, but because of weird seat math, you claim a historic mandate? That's like scoring fewer goals but claiming you won because you had more possession. Fix your math, bro.",
